import json, re, itertools, heapq
with open('/workspace/DEMOS.json') as f:
    data = json.load(f)

def find_direct_changes(inp, out):
    """Find direct character-level changes between input and output."""
    if inp == out:
        return []

    # Find longest common prefix
    n = min(len(inp), len(out))
    prefix = 0
    while prefix < n and inp[prefix] == out[prefix]:
        prefix += 1

    # Find longest common suffix (after prefix)
    s_in = len(inp)
    s_out = len(out)
    while s_in > prefix and s_out > prefix and inp[s_in-1] == out[s_out-1]:
        s_in -= 1
        s_out -= 1

    if prefix >= s_in:
        return []

    return prefix, s_in, s_out

def generate_direct_candidates(examples):
    """Generate candidate programs from direct prefix/suffix analysis."""
    candidates = {}  # (A, B) -> set of example indices it fixes

    for idx, (inp, out) in enumerate(examples):
        if inp == out:
            continue

        result = find_direct_changes(inp, out)
        if not result:
            continue

        prefix, s_in, s_out = result
        in_region = inp[prefix:s_in]
        out_region = out[prefix:s_out]

        # Generate all valid (A, B) pairs from regions
        for a_len in range(1, min(4, len(in_region) + 1)):
            for a_start in range(len(in_region) - a_len + 1):
                A = in_region[a_start:a_start + a_len]
                for b_len in range(min(4, len(out_region) + 1)):
                    for b_start in range(len(out_region) - b_len + 1):
                        B = out_region[b_start:b_start + b_len]
                        if A not in candidates:
                            candidates[A] = {}
                        if B not in candidates[A]:
                            candidates[A][B] = set()
                        candidates[A][B].add(idx)

    return candidates

# Test on task 3
task = data[3]
ex = [(inp, out) for inp, out in zip(task['input_examples'], task['output_examples'])]
cands = generate_direct_candidates(ex)
print(f"Total unique candidates: {len(cands)}")

# Check specific ones
solution = [('RC', 'PkK'), ('Ol', 'JX'), ('R', 'k')]
for A, B in solution:
    if A in cands and B in cands[A]:
        fixed = cands[A][B]
        print(f"replace('{A}', '{B}'): fixes {len(fixed)} examples: {sorted(fixed)}")
    else:
        print(f"replace('{A}', '{B}'): NOT FOUND")

