with open('/workspace/DEMOS.json') as f:
    data = json.load(f)
sys.path.insert(0, '/workspace')
from rewards.pbebench import reward as pbe_reward

def apply_programs(inp, programs):
    """Apply a sequence of replace programs to an input string."""
    cur = inp
    for pred, trans in programs:
        cur = cur.replace(pred, trans)
    return cur

def score_programs(programs, examples):
    """Score a program sequence: fraction of examples correctly transformed."""
    if not examples:
        return 0.0
    correct = sum(1 for inp, out in examples 
                  if apply_programs(inp, programs) == out)
    return correct / len(examples)

def validate_programs(programs, max_programs=20, max_pred_len=3, max_transform_len=3):
    """Check if a program sequence is valid."""
    if len(programs) > max_programs:
        return False
    for pred, trans in programs:
        if len(pred) < 1 or len(pred) > max_pred_len:
            return False
        if len(trans) > max_transform_len:
            return False
    return True

def extract_candidates_from_pair(inp, out):
    """Extract candidate (A, B) pairs from a single (input, output) pair."""
    if inp == out:
        return []

    # Find edit region
    prefix = 0
    while prefix < min(len(inp), len(out)) and inp[prefix] == out[prefix]:
        prefix += 1

    suffix_in = len(inp)
    suffix_out = len(out)
    while suffix_in > prefix and suffix_out > prefix and inp[suffix_in-1] == out[suffix_out-1]:
        suffix_in -= 1
        suffix_out -= 1

    if prefix >= suffix_in:
        return []

    in_region = inp[prefix:suffix_in]
    out_region = out[prefix:suffix_out]

    candidates = []
    for a_len in range(1, min(4, len(in_region) + 1)):
        for a_start in range(len(in_region) - a_len + 1):
            A = in_region[a_start:a_start + a_len]
            for b_len in range(min(4, len(out_region) + 1)):
                for b_start in range(len(out_region) - b_len + 1):
                    B = out_region[b_start:b_start + b_len]
                    candidates.append((A, B))

    return candidates

def find_programs_beam_search(examples, K_beam=50, max_programs=20, beam_width=20):
    """
    Beam search for the best program sequence.
    """
    if not examples:
        return []

    # Generate all unique direct-change candidates
    all_candidates = set()
    for inp, out in examples:
        if inp != out:
            for cand in extract_candidates_from_pair(inp, out):
                all_candidates.add(cand)

    # Also add no-op candidates (replace with self) to handle edge cases
    all_candidates = list(all_candidates)
    print(f"Generated {len(all_candidates)} direct-change candidates")

    # State: (programs_list, score)
    # Use a priority queue with negated score for max-heap behavior
    # Initial state: empty programs
    beam = [((), 0.0)]  # (tuple of (pred, trans), score)

    best_solution = None
    best_score = 0.0

    for step in range(1, max_programs + 1):
        print(f"\nStep {step}: beam size = {len(beam)}, best so far = {best_score:.2f}")
        next_beam = []

        for programs, score in beam:
            # Try adding each candidate
            for cand in all_candidates:
                pred, trans = cand
                new_programs = list(programs) + [cand]

                if not validate_programs(new_programs):
                    continue

                new_score = score_programs(new_programs, examples)

                if new_score > best_score:
                    best_score = new_score
                    best_solution = tuple(new_programs)

                if new_score >= 1.0:
                    return new_programs

                # Check if this candidate is new (not already in programs)
                # to avoid redundant programs
                if cand not in programs:
                    next_beam.append((tuple(new_programs), new_score))

        # Keep top-K states
        if next_beam:
            next_beam.sort(key=lambda x: -x[1])
            beam = next_beam[:beam_width]
        else:
            break

    if best_solution and best_score >= 1.0:
        return list(best_solution)

    return list(best_solution) if best_solution else []

# Test on task 3 (easy, 3 programs)
task = data[3]
ex = list(zip(task['input_examples'], task['output_examples']))
progs = find_programs_beam_search(ex, beam_width=100, max_programs=10)
print(f"\nFound {len(progs)} programs: {progs}")

# Verify
for inp, out in ex:
    actual = apply_programs(inp, progs)
    if actual != out:
        print(f"✗ {inp!r} → {actual!r} (expected {out!r})")

