            return False
        if len(trans) > max_transform_len:
            return False
    return True

def find_programs_greedy_iterative(examples, max_programs=20):
    """Greedy iterative program selection."""
    if not examples:
        return []

    # Pre-compute all candidates and their direct-fix counts
    all_candidates = set()
    for inp, out in examples:
        if inp != out:
            all_candidates |= extract_candidates_from_pair(inp, out)

    all_candidates = list(all_candidates)
    print(f"Total candidates: {len(all_candidates)}")

    programs = []
    max_candidates_to_try = 200  # Limit to most useful candidates

    for step in range(max_programs):
        # For each candidate, compute:
        # 1. How many currently-unfixed examples does it fix?
        # 2. Does it break any currently-fixed examples?

        best_cand = None
        best_score = 0

        for cand in all_candidates:
            if cand in programs:
                continue

            pred, trans = cand
            n_fix = 0
            n_break = 0

            for inp, out in examples:
                cur_fixed = apply_programs(inp, programs)
                if cur_fixed == out:
                    # Check if this program would break the fixed example
                    new = cur_fixed.replace(pred, trans)
                    if new != out:
                        n_break += 1
                else:
                    # Check if this program would fix it
                    new = cur_fixed.replace(pred, trans)
                    if new == out:
                        n_fix += 1

            # Score: net fixes (fixed - broken)
            score = n_fix - n_break

            if score > best_score or (score == best_score and best_cand is not None and len(cand[0]) > len(best_cand[0])):
                best_score = score
                best_cand = cand

        if best_cand is None or best_score <= 0:
