    # Pre-compute all candidates
    all_candidates = set()
    for inp, out in examples:
        if inp != out:
            all_candidates |= extract_candidates_from_pair(inp, out)

    all_candidates = list(all_candidates)
    print(f"Total candidates: {len(all_candidates)}")

    programs = []

    for step in range(max_programs):
        best_cand = None
        best_score = 0

        for cand in all_candidates:
            if cand in programs:
                continue

            pred, trans = cand
            n_fix = 0
            n_break = 0

            for inp, out in examples:
                cur_fixed = apply_programs(inp, programs)
                if cur_fixed == out:
                    new = cur_fixed.replace(pred, trans)
                    if new != out:
                        n_break += 1
                else:
                    new = cur_fixed.replace(pred, trans)
                    if new == out:
                        n_fix += 1

            # Score: net fixes, with tiebreaker by specificity (longer predicate)
            score = n_fix - n_break * 2  # Penalize breaking more heavily
            if score > best_score or (score == best_score and best_cand is not None 
                                       and len(cand[0]) > len(best_cand[0])):
                best_score = score
                best_cand = cand

        if best_cand is None or best_score <= 0:
