            for cand in candidates_for_example:
                if cand in programs:
                    continue

                pred, trans = cand
                # Check if this candidate fixes this example
                test = apply_programs(inp, programs + [cand])
                if test == out:
                    # Also check it doesn't break too many other examples
                    n_break = 0
                    for i2, inp2, out2 in examples:
                        if i2 == idx:
