def extract_candidates_from_pair(inp, out):
    if inp == out:
        return set()
    prefix = 0
    while prefix < min(len(inp), len(out)) and inp[prefix] == out[prefix]:
        prefix += 1
    suffix_in = len(inp)
    suffix_out = len(out)
    while suffix_in > prefix and suffix_out > prefix and inp[suffix_in-1] == out[suffix_out-1]:
        suffix_in -= 1
        suffix_out -= 1
    if prefix >= suffix_in:
        return set()
    in_region = inp[prefix:suffix_in]
    out_region = out[prefix:suffix_out]
    candidates = set()
    for a_len in range(1, min(4, len(in_region) + 1)):
        for a_start in range(len(in_region) - a_len + 1):
            A = in_region[a_start:a_start + a_len]
            for b_len in range(min(4, len(out_region) + 1)):
                for b_start in range(len(out_region) - b_len + 1):
                    B = out_region[b_start:b_start + b_len]
                    candidates.add((A, B))
    return candidates

def apply_programs(inp, programs):
    cur = inp
    for pred, trans in programs:
        cur = cur.replace(pred, trans)
    return cur

def find_programs_greedy_with_residual(examples, max_programs=20):
    if not examples:
        return []

    all_candidates = set()
    for inp, out in examples:
        if inp != out:
            all_candidates |= extract_candidates_from_pair(inp, out)

    all_candidates = list(all_candidates)
    programs = []

    for step in range(max_programs):
        best_cand = None
        best_score = 0

