            n_fix = 0
            n_break = 0

            for inp, out in examples:
                cur_fixed = apply_programs(inp, programs)
                if cur_fixed == out:
                    new = cur_fixed.replace(pred, trans)
                    if new != out:
                        n_break += 1
                else:
                    new = cur_fixed.replace(pred, trans)
                    if new == out:
                        n_fix += 1

            score = n_fix - n_break * 2
            if score > best_score or (score == best_score and best_cand is not None 
                                       and len(cand[0]) > len(best_cand[0])):
                best_score = score
                best_cand = cand

        if best_cand is None or best_score <= 0:
            break

        programs.append(best_cand)

    # Residual fixing
    for _ in range(max_programs * 2):
        unfixed_indices = [i for i, (inp, out) in enumerate(examples) 
                          if apply_programs(inp, programs) != out]
        if not unfixed_indices:
            break

        fixed_this_round = False
        for idx in unfixed_indices:
            if len(programs) >= max_programs:
                break

            inp, out = examples[idx]
            current = apply_programs(inp, programs)
            remaining_diff = extract_candidates_from_pair(current, out)

            for cand in remaining_diff:
                if cand in programs:
                    continue

                test = apply_programs(inp, programs + [cand])
                if test == out:
                    n_break = sum(1 for i2, (inp2, out2) in enumerate(examples) 
                                 if i2 != idx and apply_programs(inp2, programs) == out2
                                 and apply_programs(inp2, programs + [cand]) != out2)

                    if n_break <= 2:
                        programs.append(cand)
                        fixed_this_round = True
                        break

        if not fixed_this_round:
            break

    return programs

# Run on all tasks
results = []
total_correct = 0
total_tasks = len(data)

for i, task in enumerate(data):
    ex = list(zip(task['input_examples'], task['output_examples']))
    progs = find_programs_greedy_with_residual(ex, max_programs=20)
    correct = sum(1 for inp, out in ex if apply_programs(inp, progs) == out)
    total_correct += correct
    status = "PASS" if correct == len(ex) else f"FAIL({correct}/{len(ex)})"
    results.append(status)

print(f"\n{'='*60}")
print(f"Results: {sum(1 for r in results if r == 'PASS')}/{total_tasks} tasks passed")
print(f"Overall: {total_correct}/{total_tasks*50} examples correct")

# Show failures
for i, (task, status) in enumerate(zip(data, results)):
    if status != "PASS":
        print(f"  Task {i} ({task['difficulty']}): {status}")

