    if inp == out:
        return set()

    prefix = 0
    while prefix < min(len(inp), len(out)) and inp[prefix] == out[prefix]:
        prefix += 1

    suffix_in = len(inp)
    suffix_out = len(out)
    while suffix_in > prefix and suffix_out > prefix and inp[suffix_in-1] == out[suffix_out-1]:
        suffix_in -= 1
        suffix_out -= 1

    if prefix >= suffix_in and prefix >= suffix_out:
        # Edge case: no common prefix and no common suffix, full replacement
        in_region = inp
        out_region = out
    else:
        in_region = inp[prefix:suffix_in]
        out_region = out[prefix:suffix_out]

    candidates = set()

    if len(in_region) == 0:
        # Insertion: nothing to remove, just add characters
        # This happens when the output has extra characters in the middle
        for b_len in range(1, min(4, len(out_region) + 1)):
            for b_start in range(len(out_region) - b_len + 1):
                B = out_region[b_start:b_start + b_len]
                candidates.add(('', B))
    elif len(out_region) == 0:
        # Deletion: remove characters but don't add anything
        for a_len in range(1, min(4, len(in_region) + 1)):
            for a_start in range(len(in_region) - a_len + 1):
                A = in_region[a_start:a_start + a_len]
                candidates.add((A, ''))
    else:
        # Substitution or mixed: replace some characters with others
        for a_len in range(1, min(4, len(in_region) + 1)):
            for a_start in range(len(in_region) - a_len + 1):
                A = in_region[a_start:a_start + a_len]
                for b_len in range(min(4, len(out_region) + 1)):
                    for b_start in range(len(out_region) - b_len + 1):
                        B = out_region[b_start:b_start + b_len]
                        candidates.add((A, B))

