# Run greedy
programs = []
for step in range(15):
    best_cand = None
    best_score = -1

    for cand in all_candidates:
        if cand in programs:
            continue
        pred, trans = cand

        n_fix = 0
        n_break = 0
        for inp, out in ex:
            cur = apply_programs(inp, programs)
            if cur == out:
                new = cur.replace(pred, trans)
                if new != out:
                    n_break += 1
            else:
                new = cur.replace(pred, trans)
                if new == out:
                    n_fix += 1

