                        candidates.add((char_before, B))

    return candidates

def find_programs_v4(examples, max_programs=20):
    if not examples:
        return []

    all_candidates = set()
    for inp, out in examples:
        if inp != out:
            all_candidates |= extract_candidates_v3(inp, out)

    all_candidates = list(all_candidates)
    programs = []

    # Phase 1: Greedy selection
    for step in range(max_programs):
        best_cand = None
        best_score = -1

        for cand in all_candidates:
            if cand in programs:
