            if not found:
                # Try 3-program combinations
                for c1 in cands_list:
                    if found:
                        break
                    for c2 in cands_list:
                        if c1 == c2:
                            continue
                        for c3 in cands_list:
                            if c1 == c3 or c2 == c3:
                                continue
                            if c3 in programs:
                                continue
                            test = apply_programs(inp, programs + [c1, c2, c3])
                            if test == out:
                                n_break = 0
                                for i2, (inp2, out2) in enumerate(examples):
                                    if i2 == idx:
                                        continue
                                    cur2 = apply_programs(inp2, programs)
                                    if cur2 == out2:
                                        new2 = cur2.replace(c1[0], c1[1]).replace(c2[0], c2[1]).replace(c3[0], c3[1])
                                        if new2 != out2:
                                            n_break += 1
                                if n_break <= 2:
                                    programs.append(c1)
                                    programs.append(c2)
                                    programs.append(c3)
                                    print(f"    Triple fix for {idx}: replace({c1[0]!r}, {c1[1]!r}), replace({c2[0]!r}, {c2[1]!r}), replace({c3[0]!r}, {c3[1]!r})")
                                    found = True
                                    break
                        if found:
                            break

    return programs

