print(f"\nTime: {elapsed:.2f}s")
print(f"Found {len(progs)} programs")
print(f"Correct: {correct}/{len(ex)}")
for p in progs:
    print(f"  replace('{p[0]}', '{p[1]}')")

# Test on all tasks
results = []
total_correct = 0
for i, task in enumerate(data):
    ex = list(zip(task['input_examples'], task['output_examples']))
    progs = find_programs_v4(ex, max_programs=20)
    correct = sum(1 for inp, out in ex if apply_programs(inp, progs) == out)
