import json, time, copy

with open('/workspace/DEMOS.json') as f:
    data = json.load(f)

def apply_programs(inp, programs):
    cur = inp
    for pred, trans in programs:
        cur = cur.replace(pred, trans)
    return cur

def extract_candidates_v8(inp, out):
    if inp == out:
        return set()

    prefix = 0
    while prefix < min(len(inp), len(out)) and inp[prefix] == out[prefix]:
        prefix += 1

    suffix_in = len(inp)
    suffix_out = len(out)
    while suffix_in > prefix and suffix_out > prefix and inp[suffix_in-1] == out[suffix_out-1]:
        suffix_in -= 1
        suffix_out -= 1

    in_region = inp[prefix:suffix_in]
    out_region = out[prefix:suffix_out]

    candidates = set()

    def add_standard(in_reg, out_reg):
        if len(in_reg) > 0 and len(out_reg) > 0:
            for a_len in range(1, min(4, len(in_reg) + 1)):
                for a_start in range(len(in_reg) - a_len + 1):
                    A = in_reg[a_start:a_start + a_len]
                    for b_len in range(min(4, len(out_reg) + 1)):
                        for b_start in range(len(out_reg) - b_len + 1):
                            B = out_reg[b_start:b_start + b_len]
                            candidates.add((A, B))
        elif len(in_reg) > 0 and len(out_reg) == 0:
            for a_len in range(1, min(4, len(in_reg) + 1)):
                for a_start in range(len(in_reg) - a_len + 1):
                    A = in_reg[a_start:a_start + a_len]
                    candidates.add((A, ''))
        elif len(in_reg) == 0 and len(out_reg) > 0:
            if prefix < len(inp):
                anchor = inp[prefix]
                for b_len in range(1, min(4, len(out_reg) + 1)):
                    for b_start in range(len(out_reg) - b_len + 1):
                        B = out_reg[b_start:b_start + b_len] + anchor
                        candidates.add((anchor, B))
            if prefix > 0:
                char_before = inp[prefix - 1]
                for b_len in range(1, min(4, len(out_reg) + 1)):
                    for b_start in range(len(out_reg) - b_len + 1):
                        B = char_before + out_reg[b_start:b_start + b_len]
                        candidates.add((char_before, B))

    # Main region
    add_standard(in_region, out_region)

    # Split region (for multi-step edits)
    if len(in_region) >= 2:
        for split in range(1, len(in_region)):
            A1 = in_region[:split]
            B1 = out_region[:split]
            A2 = in_region[split:]
            B2 = out_region[split:]
            if len(A1) >= 1 and len(A1) <= 3 and len(B1) <= 3:
                candidates.add((A1, B1))
            if len(A2) >= 1 and len(A2) <= 3 and len(B2) <= 3:
                candidates.add((A2, B2))

    # Extend left by 1 char (to capture patterns like 'Au' → 'Ap')
    if prefix > 0:
        extended_in = inp[prefix - 1] + in_region
        extended_out = out[prefix - 1] + out_region
        add_standard(extended_in, extended_out)

    return candidates

def find_programs(examples, max_programs=20):
    if not examples:
        return []

    all_candidates = set()
    for inp, out in examples:
        if inp != out:
            all_candidates |= extract_candidates_v8(inp, out)

    all_candidates = list(all_candidates)
    programs = []

    # Phase 1: Greedy
    for step in range(max_programs):
        best_cand = None
        best_score = -1
        for cand in all_candidates:
            if cand in programs:
                continue
            pred, trans = cand
            n_fix = 0
            n_break = 0
            for inp, out in examples:
                cur = apply_programs(inp, programs)
                if cur == out:
                    new = cur.replace(pred, trans)
                    if new != out:
                        n_break += 1
                else:
                    new = cur.replace(pred, trans)
                    if new == out:
                        n_fix += 1
            score = n_fix - n_break * 2
            if score > best_score or (score == best_score and best_cand is not None and len(cand[0]) > len(best_cand[0])):
                best_score = score
                best_cand = cand
        if best_cand is None or best_score <= 0:
            break
        programs.append(best_cand)

    # Phase 2: Single-program residual
    for _ in range(max_programs * 2):
        unfixed = [i for i, (inp, out) in enumerate(examples) if apply_programs(inp, programs) != out]
        if not unfixed:
            break
        fixed_any = False
        for idx in unfixed:
            if len(programs) >= max_programs:
                break
            inp, out = examples[idx]
            current = apply_programs(inp, programs)
            cands = extract_candidates_v8(current, out)
            for c in cands:
                if c in programs:
                    continue
                if apply_programs(inp, programs + [c]) == out:
                    n_break = sum(1 for i2, (inp2, out2) in enumerate(examples)
                                if i2 != idx and apply_programs(inp2, programs) == out2
                                and apply_programs(inp2, programs + [c]) != out2)
                    if n_break <= 2:
                        programs.append(c)
                        fixed_any = True
                        break
        if not fixed_any:
            break

    # Phase 3: Multi-program residual (pairs)
    unfixed = [i for i, (inp, out) in enumerate(examples) if apply_programs(inp, programs) != out]
    if unfixed and len(programs) < max_programs - 1:
        for idx in unfixed:
            if len(programs) >= max_programs - 1:
                break
            inp, out = examples[idx]
            current = apply_programs(inp, programs)
            cands = extract_candidates_v8(current, out)
            cands_list = [c for c in cands if c not in programs]
            found = False
            for c1 in cands_list:
                if found:
                    break
                for c2 in cands_list:
                    if c1 == c2:
                        continue
                    if c2 in programs:
                        continue
                    test = apply_programs(inp, programs + [c1, c2])
                    if test == out:
                        n_break = sum(1 for i2, (inp2, out2) in enumerate(examples)
                                    if i2 != idx and apply_programs(inp2, programs) == out2
                                    and apply_programs(inp2, programs + [c1, c2]) != out2)
                        if n_break <= 2:
                            programs.append(c1)
                            programs.append(c2)
                            found = True
                            break
            if not found:
                # Triple
                for c1 in cands_list:
                    if found:
                        break
                    for c2 in cands_list:
                        if found:
                            break
                        for c3 in cands_list:
                            if c1 == c2 or c1 == c3 or c2 == c3:
                                continue
                            if c3 in programs:
                                continue
                            test = apply_programs(inp, programs + [c1, c2, c3])
                            if test == out:
                                n_break = sum(1 for i2, (inp2, out2) in enumerate(examples)
                                            if i2 != idx and apply_programs(inp2, programs) == out2
                                            and apply_programs(inp2, programs + [c1, c2, c3]) != out2)
                                if n_break <= 2:
                                    programs.append(c1)
                                    programs.append(c2)
                                    programs.append(c3)
                                    found = True
                                    break

    return programs

# Test on all tasks
results = []
total_correct = 0
total_time = 0
for i, task in enumerate(data):
    ex = list(zip(task['input_examples'], task['output_examples']))
    start = time.time()
    progs = find_programs(ex, max_programs=20)
    elapsed = time.time() - start
    total_time += elapsed

    correct = sum(1 for inp, out in ex if apply_programs(inp, progs) == out)
    total_correct += correct
    status = "PASS" if correct == len(ex) else f"FAIL({correct}/{len(ex)})"
    results.append(status)

print(f"\n{'='*60}")
print(f"Results: {sum(1 for r in results if r == 'PASS')}/{len(data)} tasks passed")
print(f"Overall: {total_correct}/{len(data)*50} examples correct")
print(f"Total time: {total_time:.2f}s")

failures = [(i, r) for i, r in enumerate(results) if r != 'PASS']
print(f"\nFailures ({len(failures)}):")
for i, r in failures:
    print(f"  Task {i}: {r}")

