            if cand in programs:
                continue
            pred, trans = cand
            n_fix = 0
            n_break = 0
            for inp, out in examples:
                cur = apply_programs(inp, programs)
                if cur == out:
                    new = cur.replace(pred, trans)
                    if new != out:
                        n_break += 1
                else:
                    new = cur.replace(pred, trans)
                    if new == out:
                        n_fix += 1
